    if (!fromMuteToggle) {
        if (val > 0) {
            currentVolume = val;
            lastVolume = val;
            isMuted = false;
        } else {
            currentVolume = 0;
            isMuted = true;
        }
    } else {
        if (isMuted) {
            isMuted = false;
            currentVolume = lastVolume || 50;
        } else {
            isMuted = true;
            if (currentVolume > 0) lastVolume = currentVolume;
            currentVolume = 0;
        }
