            refreshPreview();
        };

        updateTreeResetButton(type);

        // Biomes
        const biomesContainer = wrapper!.querySelector(`#biomes-${type}`) as HTMLElement;
        const allBiomes: BiomeType[] = ['forest', 'desert', 'tundra', 'plains', 'city'];
        if (biomesContainer.children.length === 0) {
