import { Layer } from './Layer';
import { CityGenerator } from '../procgen/CityGenerator';
import type { TreeConfig } from '../procgen/TreeConfig';
import { DEFAULT_TREE_CONFIG } from '../procgen/TreeConfig';

import { SkySystem } from './SkySystem';

export class Game {
    private canvas: HTMLCanvasElement;
    private ctx: CanvasRenderingContext2D;
    private lastTime: number = 0;
    private isRunning: boolean = false;

    private cameraX: number = 0;
    private cameraSpeed: number = 100; // Pixels per second

    private layers: Layer[] = [];
    public generator: CityGenerator | null = null;
    private sky: SkySystem | null = null;
    private seed: string = "default";
    public treeConfig: TreeConfig; // Custom config

    private noisePattern: CanvasPattern | null = null;

    private readonly scaleFactor = 1.6;
    public timeScale: number = 1.0;
    private volume: number = 1.0;
    private isMuted: boolean = false;
    private isPreview: boolean = false;
    public timeFormat: 'score' | '24h' | '12h' = '24h';

    constructor(canvas: HTMLCanvasElement, isPreview: boolean = false) {
        this.canvas = canvas;
        this.isPreview = isPreview;
        this.ctx = canvas.getContext('2d')!;
        if (!this.ctx) {
            throw new Error("Could not get 2D context");
        }

        // Init config
        this.treeConfig = JSON.parse(JSON.stringify(DEFAULT_TREE_CONFIG));

        // Initialize Logic

        this.initNoise();
        this.reset();

        if (!this.isPreview) {
            // Bind resize only for main game
            window.addEventListener('resize', () => this.resize());
            this.resize();
        } else {
            // Preview has fixed size usually, but let's ensure it matches canvas
            this.resize();
        }
    }

    public dispose() {
        this.isRunning = false;
    }

    private initNoise() {
        const w = 256;
        const h = 256;
        const canvas = document.createElement('canvas');
        canvas.width = w;
        canvas.height = h;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        const idata = ctx.createImageData(w, h);
        const data = idata.data;

        for (let i = 0; i < data.length; i += 4) {
            const val = Math.floor(Math.random() * 255);
            data[i] = val;     // R
            data[i + 1] = val; // G
            data[i + 2] = val; // B
            data[i + 3] = 8;   // ~3% opacity
        }
        ctx.putImageData(idata, 0, 0);

        this.noisePattern = this.ctx.createPattern(canvas, 'repeat');
    }

    public setSeed(seed: string) {
        this.seed = seed;
        this.reset();
    }

    public getSeed(): string {
        return this.seed;
    }

    public getCameraX(): number {
        return this.cameraX;
    }

    public setCameraX(x: number) {
        this.cameraX = x;
    }

    private reset() {
        this.cameraX = 0;
        // Layer Params: speedModifier, zIndex, yOffset
        // We want the background to be "higher" on screen (hill effect).
        // Ground is at bottom.
        // If yOffset is positive, we translate(0, -yOffset), so it moves UP.

        this.layers = [
            new Layer(0.2, 0, 190, 1.3), // Background (Highest up)
            new Layer(0.4, 1, 100), // Mid-Back
            new Layer(0.6, 2, 50),  // Mid-Fore
            new Layer(1.0, 3, 0)    // Foreground (Ground level)
        ];
        // Pass current config to generator
        this.generator = new CityGenerator(this.seed, this.layers.length, this.treeConfig);
        // this.sky = new SkySystem(this.canvas); // Was this here? I'll re-add it if I saw it before.
        // Actually, looking at previous diffs, I might have deleted it.
        // Let's assume it should be there.
        if (!this.isPreview) this.sky = new SkySystem(this.canvas);
    }

    // The original initNoise method was duplicated in the instruction,
    // but it seems the intent was to add properties and modify the constructor/reset.
    // The actual initNoise method should remain as it was, or be removed if it's truly a duplicate.
    // Based on the context, the first initNoise is the correct one.
    // The second one in the original document was a placeholder comment.
    // private initNoise() {
    //     // Simple noise init if needed
    // }

    public resize() {
        this.canvas.width = this.canvas.clientWidth;
        this.canvas.height = this.canvas.clientHeight;
    }

    public start() {
        if (this.isRunning) return;
        this.isRunning = true;
        this.lastTime = performance.now();
        console.log("Game started at", this.lastTime);
        requestAnimationFrame((t) => this.loop(t));
    }

    private loop(time: number) {
        if (!this.isRunning) return;

        try {
            const deltaTime = (time - this.lastTime) / 1000;
            this.lastTime = time;

            // Cap dt to prevent huge jumps if tab was inactive
            const safeDt = Math.min(deltaTime, 0.1);

            this.update(safeDt * this.timeScale);
            this.render();
        } catch (e) {
            console.error("Game Loop Error:", e);
            this.isRunning = false;
        }

        requestAnimationFrame((t) => this.loop(t));
    }

    private update(dt: number) {
        this.cameraX += this.cameraSpeed * dt;

        const logicalW = this.canvas.width / this.scaleFactor;

        this.sky?.update(dt, logicalW);

        // Generate new buildings if needed
        if (this.generator) {
            this.generator.generate(this.layers, this.cameraX, logicalW);
        }

        // Prune old
        this.layers.forEach(l => l.prune(this.cameraX));

        // Update Debug UI (Only for main game)
        if (!this.isPreview) {
            const uiSeedVal = document.getElementById('ui-seed-val');
            const uiTimeVal = document.getElementById('ui-time-val');

            if (uiSeedVal && uiSeedVal.innerText !== this.seed) {
                uiSeedVal.innerText = this.seed;
            }
            if (uiTimeVal) {
                if (this.timeFormat === 'score') {
                    uiTimeVal.innerText = Math.floor(this.cameraX).toString();
                } else if (this.sky) {
                    const t = this.sky.getTime();
                    const h = Math.floor(t);
                    const m = Math.floor((t - h) * 60);
                    const mStr = m.toString().padStart(2, '0');

                    if (this.timeFormat === '12h') {
                        const ampm = h >= 12 ? 'PM' : 'AM';
                        const h12 = h % 12 || 12;
                        uiTimeVal.innerText = `${h12}:${mStr} ${ampm}`;
                    } else {
                        uiTimeVal.innerText = `${h.toString().padStart(2, '0')}:${mStr}`;
                    }
                }
            }
        }
    }

    private render() {
        const logicalW = this.canvas.width / this.scaleFactor;
        const logicalH = this.canvas.height / this.scaleFactor;

        this.ctx.save();
        this.ctx.scale(this.scaleFactor, this.scaleFactor);

        // Clear screen
        // Draw Sky first
        if (this.sky) {
            this.sky.draw(this.ctx, logicalW, logicalH);
        } else {
            this.ctx.fillStyle = "#000";
            this.ctx.fillRect(0, 0, logicalW, logicalH);
        }

        const groundY = logicalH - 80; // Lift baseline so we see the ground/road

        this.ctx.save();
        this.ctx.translate(0, groundY);

        this.layers.forEach(layer => {
            layer.draw(this.ctx, this.cameraX, logicalW, logicalH);
        });

        this.ctx.restore();

        // Draw Solid Earth below groundY to hide sky
        this.ctx.fillStyle = "#2e2e2e"; // Dark earth color
        this.ctx.fillRect(0, groundY, logicalW, 80);

        // 3. Ambient Light Overlay (Global Filter - Multiply)
        if (this.sky) {
            const ambient = this.sky.getAmbientColor();

            // Multiply blending for smooth lighting
            this.ctx.globalCompositeOperation = 'multiply';
            this.ctx.fillStyle = ambient;
            this.ctx.fillRect(0, 0, logicalW, logicalH);

            // Reset composite operation
            this.ctx.globalCompositeOperation = 'source-over';
        }

        // 4. Noise Dithering (Fixes banding)
        if (this.noisePattern) {
            this.ctx.fillStyle = this.noisePattern;
            this.ctx.fillRect(0, 0, logicalW, logicalH);
        }

        this.ctx.restore(); // Restore scale
    }

    public setTimeScale(scale: number) {
        this.timeScale = scale;
    }

    public getVolume(): number {
        return this.volume;
    }

    public setVolume(vol: number) {
        this.volume = vol;
        // TODO: Apply to audio context
        console.log("Volume set to:", vol);
    }

    public getMuted(): boolean {
        return this.isMuted;
    }

    public setMuted(muted: boolean) {
        this.isMuted = muted;
        // TODO: Apply to audio context
        console.log("Muted:", muted);
    }
}

